/** Writes docs/portal-maps/INTAKE-COVERAGE.md: every intake field, the request path it fills and the walkthrough screen it comes from. */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { FILING_KINDS } from "../lib/intake/forms.ts";
import { allFields } from "../lib/intake/build.ts";

const esc = (s: string) => s.replace(/\|/g, "\\|").replace(/\n/g, " ");
const lines: string[] = [
  "# Intake coverage",
  "",
  "Generated by `npm run coverage` in `web/` from `web/lib/intake/forms.ts`. Do not edit by hand.",
  "",
  "Each portal intake form collects the fields its state walkthrough found. The table lists, per filing kind,",
  "the field label the client sees, the engine request path it fills, whether it is required, and the",
  "walkthrough screen it comes from. Paths under `intake.portal.*` and `payroll.stateAnswers.*` are kept on",
  "the filing for the adapters; the engine has no first-class field for them yet.",
  "",
];
for (const k of FILING_KINDS) {
  const fields = allFields(k);
  lines.push(`## ${k.title} (\`${k.id}\`)`, "", `${k.summary} Walkthrough: [${k.map}](./${k.map}). Engine type \`${k.type}\`, state \`${k.state}\`.`, "");
  if (k.feeNote) lines.push(`Fees: ${k.feeNote}`, "");
  lines.push("| Section | Field | Request path | Required | Walkthrough |", "|---|---|---|---|---|");
  for (const f of fields) {
    const req = f.field.required === true ? (f.field.showIf ? "when shown" : "yes") : f.field.required === "withSiblings" ? "with its group" : "";
    lines.push(`| ${esc(f.section)} | ${esc(f.field.label)} | \`${f.path}\` | ${req} | ${esc(f.field.ref ?? f.group?.ref ?? "")} |`);
  }
  lines.push("", "Authorizations the client grants (and confirms again on the approval page):", "");
  for (const a of k.authorizations) lines.push(`- **${a.id}** (${esc(a.ref)}): ${a.text}`);
  lines.push("", "Not covered yet:", "");
  for (const g of k.gaps) lines.push(`- ${g}`);
  lines.push("");
}
const out = fileURLToPath(new URL("../../docs/portal-maps/INTAKE-COVERAGE.md", import.meta.url));
writeFileSync(out, lines.join("\n"));
console.log(`wrote ${out}`);
